/**
 * Try-it samples: real DHARMA passages with their real gaps, so nobody needs inscription text to hand.
 * Generated by scripts/build_samples.py from benchmark TRAIN inscriptions only (tests/test_samples.py and
 * samples.test.ts check that no val/test inscription is here). Do not edit the JSON by hand.
 */
import { useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import type { Level } from '../lib/levels';
import imagesJson from './sample-images.json';
import samplesJson from './samples.json';

export type Era = 'pallava' | 'pandya' | 'chola' | 'rashtrakuta' | 'vijayanagara';

export interface Sample {
  id: string;
  inscription_id: string;
  split: 'train';
  /** benchmark/blank.jsonl ids of the gaps in this passage (letters lost on the stone, never restored). */
  blank_ids: string[];
  era: Era;
  era_ta: string;
  era_en: string;
  /** Suggested level for "Learn with this". */
  learn_level: Level;
  title_ta: string;
  title_en: string;
  place_ta: string;
  place_en: string;
  /** The edition's own title: place, ruler and year as DHARMA gives them. */
  edition_title: string;
  ruler: string | null;
  regnal_year: number | null;
  dynasty: string | null;
  why_ta: string;
  why_en: string;
  /** 1-based first and last line of the edition text in this passage. */
  lines: [number, number];
  gaps: number;
  text_iso: string;
  text_tamil: string;
  dharma_url: string;
  source_url: string;
  licence: string;
  licence_url: string;
}

export interface SampleImage {
  id: string;
  /** The gallery sample whose text the picture shows. */
  sample: string;
  script: 'tamil' | 'iso15919';
  style: 'stone' | 'hero' | 'photo' | 'page';
  title_en: string;
  title_ta: string;
  /** Path under the site root (app/web/public), e.g. "samples/stone-chola.jpg". */
  file: string;
  inscription_id: string;
  lines: string[];
  /** What a perfect read returns: lines joined by "\n"; a chipped patch is [?N] with N only approximate. */
  expected_text: string;
  credit: string;
  dharma_url: string;
  licence: string;
  licence_url: string;
}

export const SAMPLES = samplesJson as Sample[];
export const SAMPLE_IMAGES = imagesJson as SampleImage[];
export const ERAS: Era[] = ['pallava', 'pandya', 'chola', 'rashtrakuta', 'vijayanagara'];

export function sampleById(id: string | null | undefined): Sample | undefined {
  return id ? SAMPLES.find((s) => s.id === id) : undefined;
}

export function sampleByInscription(inscriptionId: string | null | undefined): Sample | undefined {
  return inscriptionId ? SAMPLES.find((s) => s.inscription_id === inscriptionId) : undefined;
}

/** URL of a sample image, respecting Vite's base path. */
export function sampleImageUrl(image: SampleImage): string {
  return `${import.meta.env.BASE_URL}${image.file}`;
}

export const restoreHref = (s: Sample) => `/restore?sample=${encodeURIComponent(s.id)}`;
export const learnHref = (s: Sample) =>
  `/learn?inscription=${encodeURIComponent(s.inscription_id)}&level=${s.learn_level}&sample=${encodeURIComponent(s.id)}`;

/**
 * The sample named by `?sample=<id>` on /restore, as the text and script the restore form should start with.
 * Tamil is the default script, as for a learner; English readers get the ISO-15919 transliteration.
 */
export function useRestoreSample(lang: 'ta' | 'en'): { sample: Sample; text: string; script: 'tamil' | 'iso15919' } | null {
  const [params] = useSearchParams();
  const id = params.get('sample');
  return useMemo(() => {
    const sample = sampleById(id);
    if (!sample) return null;
    return lang === 'ta'
      ? { sample, text: sample.text_tamil, script: 'tamil' as const }
      : { sample, text: sample.text_iso, script: 'iso15919' as const };
  }, [id, lang]);
}
